  "devdoc": {
    "events": {
      "AdminChanged(address,address)": {
        "details": "Emitted when the admin account has changed."
      },
      "BeaconUpgraded(address)": {
        "details": "Emitted when the beacon is changed."
      },
      "DealStruck(bytes32,address)": {
        "custom:deprecated": "V2 name; emitted alongside `AgreementStruck` for old indexers."
      },
      "Initialized(uint8)": {
        "details": "Triggered when the contract has been initialized or reinitialized."
      },
      "Upgraded(address)": {
        "details": "Emitted when the implementation is upgraded."
      }
    },
    "kind": "dev",
    "methods": {
      "acceptOffer(bytes32)": {
        "details": "Publication accepts a pending offer → agreement."
      },
      "canRead(bytes32,address)": {
        "details": "Read access for `genesis`. The safe, the genesis author and reviewers      all read a genesis once it is under an agreement or an offer; an      unknown genesis (no author) is never readable."
      },
      "canReview(bytes32,address)": {
        "details": "True iff `who` is a reviewer and `genesis` is under an agreement or offer."
      },
      "constructor": {
        "custom:oz-upgrades-unsafe-allow": "constructor"
      },
      "getDealCount()": {
        "custom:deprecated": "V2 name; use `getAgreementCount`."
      },
      "getDeals(uint256,uint256)": {
        "custom:deprecated": "V2 name; use `getAgreements`."
      },
      "hasAgreement(bytes32)": {
        "details": "True iff `genesis` is currently under an agreement. Callers convert      their content reference → genesis via the shared helper before calling."
      },
      "hasDeal(bytes32)": {
        "custom:deprecated": "V2 name; use `hasAgreement`."
      },
      "hasEnded(bytes32)": {
        "details": "True iff the author has ended this genesis for this publication.      Permanent: `makeOffer` and `acceptOffer` revert for an ended genesis."
      },
      "makeOffer(bytes32,string)": {
        "details": "Append a version and place the document. Whitelisted author or safe      → agreement; anyone else → offer. Editing an existing offer just      appends another version (stays an offer). Editing content that is      already an agreement appends a version and leaves the agreement intact."
      },
      "ownerHasAgreement(address)": {
        "details": "True iff `_address` currently holds at least one agreement. Not a      publish gate: `canPublish` stays the whitelist predicate."
      },
      "proxiableUUID()": {
        "details": "Implementation of the ERC1822 {proxiableUUID} function. This returns the storage slot used by the implementation. It is used to validate the implementation's compatibility when performing an upgrade. IMPORTANT: A proxy pointing at a proxiable contract should not be considered proxiable itself, because this risks bricking a proxy that upgrades to it, by delegating to itself until out of gas. Thus it is critical that this function revert if invoked through a proxy. This is guaranteed by the `notDelegated` modifier."
      },
      "reinitializeV3()": {
        "details": "Run once at upgrade time on a live proxy, so `agreementsHeldBy`      reflects the agreements struck while the proxy ran V2. The list holds      unique genesis and the reinitializer can only run once, so nothing is      cleared first. A fresh deployment does not need it: the list is empty      and the call is a no-op."
      },
      "retract(bytes32)": {
        "details": "Retract, asymmetric by caller:      - author  → terminal. An agreement ends for good: `_ended` is set and        the latest version is tombstoned, then the genesis leaves both sets.        A pending offer with no agreement is simply withdrawn, and is not        marked ended — there is nothing to end.      - safe     → not terminal. An agreement is demoted back to a pending        offer; a pending offer is rejected. The safe may accept again."
      },
      "setReviewer(address,bool)": {
        "details": "Add or remove a reviewer. Idempotent; reverts on the zero address."
      },
      "upgradeTo(address)": {
        "custom:oz-upgrades-unsafe-allow-reachable": "delegatecall",
        "details": "Upgrade the implementation of the proxy to `newImplementation`. Calls {_authorizeUpgrade}. Emits an {Upgraded} event."
      },
      "upgradeToAndCall(address,bytes)": {
        "custom:oz-upgrades-unsafe-allow-reachable": "delegatecall",
        "details": "Upgrade the implementation of the proxy to `newImplementation`, and subsequently execute the function call encoded in `data`. Calls {_authorizeUpgrade}. Emits an {Upgraded} event."
      }
    },
    "title": "S2SPublicationModuleV3",
    "version": 1
  },
